const b = $input.first().json.body || {};
const rows = Array.isArray(b.rows) ? b.rows : [];
const linhas = rows.map((r,i)=>Object.entries(r).map(([k,v])=>`${k}: ${v}`).join(' | ')).join('\n');
return [{ json: { ...b, rows, n: rows.length, linhas, analise_txt: b.analise ? JSON.stringify(b.analise) : '' } }];

